    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i + 1])  // Each element in result is the maximum up to that index
{
    var maxSoFar := numbers[0];
    var n := |numbers|;
    result := new int[n];

    result[0] := maxSoFar;

    // Iterate through the input list starting from the second element
    var i := 1;
    while i < n
        invariant 1 <= i <= n  // i is always a valid index
        invariant forall j :: 0 <= j < i ==> result[j] == Max(numbers[0..j + 1])  // The result so far is correct
    {
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i];
        }
        result[i] := maxSoFar;
        i := i + 1;
    }
